// 蘑菇 (2).glb → 内联网格数据（由 tools/glb2hero.mjs 生成，勿手改）
// 顶点 3265，三角 4790，贴图 666KB base64
import { Vs } from './05-three.js';

const dec = (b64, T) => {
  const bin = atob(b64);
  const u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return new T(u8.buffer);
};

let _mesh = null;
export function heroMesh() {
  return (_mesh ??= {
    pos: dec(HERO_MESH.pos, Float32Array),
    nor: dec(HERO_MESH.nor, Float32Array),
    uv: dec(HERO_MESH.uv, Float32Array),
    idx: dec(HERO_MESH.idx, Uint32Array),
  });
}

let _map = null;
export function heroMap() {
  if (_map) return _map;
  const tex = new Vs();
  // glTF 的 UV 原点在左上，three 默认 flipY=true 会把它上下翻过来
  tex.flipY = false;
  // 先放 1x1 白，贴图解码完再替换，避免首帧采样空纹理
  const c = document.createElement('canvas');
  c.width = c.height = 1;
  const g = c.getContext('2d');
  g.fillStyle = '#fff';
  g.fillRect(0, 0, 1, 1);
  tex.image = c;
  tex.needsUpdate = true;
  if (HERO_MESH.tex) {
    const img = new Image();
    img.onload = () => ((tex.image = img), (tex.needsUpdate = true));
    img.src = HERO_MESH.tex;
  }
  return (_map = tex);
}

export const HERO_MESH = {
  verts: 3265,
  pos: "",
  nor: "",
  uv: "",
  idx: "",
  tex: "data:image/jpeg;base64,",
};
